def char_frequency(text):
    freq = {}
    for ch in text:
        freq[ch] = freq.get(ch, 0) + 1
    return freq

print(char_frequency('hello'))
# {'h': 1, 'e': 1, 'l': 2, 'o': 1}

d1 = {'a': 1, 'b': 2}
d2 = {'c': 3, 'd': 4}

# Method 1: unpacking (works everywhere)
merged = {**d1, **d2}

# Method 2: | operator (Python 3.9+)
merged = d1 | d2

# Method 3: update()
merged = d1.copy()
merged.update(d2)

print(merged)  # {'a': 1, 'b': 2, 'c': 3, 'd': 4}

d1 = {'a': 1, 'b': 2}
d2 = {'b': 2, 'a': 1}
d3 = {'a': 1, 'b': 3}

print(d1 == d2)   # True  (order does not matter)
print(d1 == d3)   # False

from collections import defaultdict

def char_counter(text):
    counter = defaultdict(int)
    for ch in text:
        counter[ch] += 1
    return dict(counter)

print(char_counter('hello world'))
# {'h': 1, 'e': 1, 'l': 3, 'o': 2, ' ': 1, 'w': 1, 'r': 1, 'd': 1}

def create_test_summary(results, start_time, end_time):
    duration = (end_time - start_time).total_seconds()
    passed = sum(1 for r in results if r['status'] == 'PASS')
    rate = round((passed / len(results)) * 100, 2) if results else 0
    return {
        'duration': duration,
        'passed': passed,
        'total': len(results),
        'pass_rate': rate
    }
